# ---- применение ----
t = open('slides.html', encoding='utf-8').read()
parts = re.split(r'(data-note=")', t)
# parts: [before, 'data-note="', rest0, 'data-note="', rest1, ...]
idx = 0
out = [parts[0]]
for i in range(1, len(parts), 2):
    marker, rest = parts[i], parts[i+1]
    end = rest.index('"')
    new_note = N[idx].replace('"', '&quot;')
    out.append(marker + new_note + rest[end:])
    idx += 1
out_t = ''.join(out)
assert idx == 29, f"слайдов с note: {idx}"
open('slides.html', 'w', encoding='utf-8').write(out_t)
print(f"переписано {idx} заметок")
